#include <set>
#include <iostream>

int main() {
    std::set<int> s = {3, 1, 4, 1, 5}; // Set automatically sorts and de-duplicates
    std::multiset<int> ms = {3, 1, 4, 1, 5};

    s.insert(4); // Fails, 4 already exists
    ms.insert(4); // Succeeds

    // Output: s is {1, 3, 4, 5} (Size 4)
    std::cout << "Set size: " << s.size() << "\n";

    // Output: ms is {1, 1, 3, 4, 4, 5} (Size 6)
    std::cout << "Multiset size: " << ms.size() << "\n";
}
